/**
 * Ray-marching material for volumetric SDF visualization.
 *
 * Renders signed distance fields as volumetric surfaces using sphere tracing.
 * Supports iso-surface extraction at arbitrary SDF thresholds.
 *
 * **Features:**
 * - GPU ray-marching with adaptive step size
 * - Central differences for surface normal computation
 * - Simple directional lighting
 * - Configurable iso-surface level
 *
 * @example
 * import { RayMarchSDFNodeMaterial } from 'three-blocks';
 * import { FullScreenQuad } from 'three/examples/jsm/postprocessing/Pass.js';
 *
 * const material = new RayMarchSDFNodeMaterial(sdfTexture);
 * const quad = new FullScreenQuad(material);
 *
 * // In render loop
 * material.fragmentNode.parameters.surface.value = 0.0; // Iso-surface level
 * material.fragmentNode.parameters.sdfTransformInverse.value.copy(sdfInverse);
 * material.fragmentNode.parameters.sdfTransform.value.copy(sdfTransform);
 * quad.render(renderer);
 *
 * @class RayMarchSDFNodeMaterial
 * @extends {NodeMaterial}
 */
export class RayMarchSDFNodeMaterial {
    /**
     * @param {THREE.Storage3DTexture} sdfTexture - 3D SDF texture to visualize
     */
    constructor(sdfTexture: THREE.Storage3DTexture);
    fragmentNode: any;
    vertexNode: any;
}
